window.RWHProjectCopy = {"vi":{"project.the-hera-resort.metadata":"KHU NGHỈ DƯỠNG / Quy Nhơn, Việt Nam","project.the-hera-resort.category":"KHU NGHỈ DƯỠNG","project.the-hera-resort.subtitle":"Kiến trúc Santorini bên Vịnh Tiên","project.the-hera-resort.description":"The Hera Resort kết nối triền núi, rừng xanh và Vịnh Tiên tại Quy Nhơn. Phương án kiến trúc mang cảm hứng Santorini, tổ chức các không gian biệt thự, căn hộ nghỉ dưỡng và bến du thuyền theo địa hình hướng biển.","project.the-hera-resort.fact.0.label":"Địa điểm","project.the-hera-resort.fact.0.value":"Quy Nhơn, Việt Nam","project.the-hera-resort.fact.1.label":"Loại hình","project.the-hera-resort.fact.1.value":"Khu nghỉ dưỡng","project.the-hera-resort.fact.2.label":"Quy mô","project.the-hera-resort.fact.2.value":"16,62 ha","project.capital-one.metadata":"THƯƠNG MẠI & VĂN PHÒNG","project.capital-one.category":"THƯƠNG MẠI & VĂN PHÒNG","project.capital-one.subtitle":"Tổ hợp thương mại và văn phòng","project.capital-one.description":"Phương án Capital One khai thác ý tưởng hành trình qua các tầng không gian, từ mặt đất, nước đến bầu trời và vũ trụ. Thiết kế kết hợp khối thương mại, văn phòng và cảnh quan, với mặt đứng kính cùng ánh sáng tạo điểm nhấn theo phương đứng.","project.capital-one.fact.0.label":"Loại hình","project.capital-one.fact.0.value":"Tổ hợp thương mại và văn phòng","project.capital-one.fact.1.label":"Tư liệu","project.capital-one.fact.1.value":"Phương án concept","project.kawara-my-an.metadata":"KHU NGHỈ DƯỠNG ONSEN / Huế, Việt Nam","project.kawara-my-an.category":"KHU NGHỈ DƯỠNG ONSEN","project.kawara-my-an.subtitle":"Không gian nghỉ dưỡng và trải nghiệm Onsen","project.kawara-my-an.description":"Kawara Mỹ An Onsen Resort tại Huế kết hợp không gian lưu trú, sân vườn và trải nghiệm tắm khoáng theo tinh thần Nhật Bản. Bộ ảnh thể hiện các khu tắm, phòng nghỉ và cảnh quan kết nối với mặt nước.","project.kawara-my-an.fact.0.label":"Địa điểm","project.kawara-my-an.fact.0.value":"Huế, Việt Nam","project.kawara-my-an.fact.1.label":"Loại hình","project.kawara-my-an.fact.1.value":"Khu nghỉ dưỡng Onsen","project.aegis-hospital.metadata":"BỆNH VIỆN","project.aegis-hospital.category":"BỆNH VIỆN","project.aegis-hospital.subtitle":"Phương án kiến trúc bệnh viện","project.aegis-hospital.description":"Phương án Aegis International Hospital tổ chức các khối tháp và khoảng xanh xen kẽ. Hồ sơ trình bày phối cảnh tổng thể, hình khối mặt đứng và các khoảng mở giữa công trình.","project.aegis-hospital.fact.0.label":"Loại hình","project.aegis-hospital.fact.0.value":"Bệnh viện quốc tế","project.aegis-hospital.fact.1.label":"Tư liệu","project.aegis-hospital.fact.1.value":"Phương án thiết kế","project.onsen-thanh-thuy.metadata":"ONSEN & CHĂM SÓC SỨC KHỎE / Phú Thọ, Việt Nam","project.onsen-thanh-thuy.category":"ONSEN & CHĂM SÓC SỨC KHỎE","project.onsen-thanh-thuy.subtitle":"Kiến trúc Ryokan và cảnh quan nghỉ dưỡng","project.onsen-thanh-thuy.description":"Concept Onsen Wellness Thanh Thuỷ lấy cảm hứng từ làng Kinosaki và kiến trúc Ryokan Nhật Bản. Trục cảnh quan mặt nước kết nối các không gian nghỉ dưỡng, phố đi bộ, sân vườn và khu trải nghiệm Onsen, hướng đến một ngôi làng chăm sóc sức khỏe gắn với thiên nhiên.","project.onsen-thanh-thuy.fact.0.label":"Địa điểm","project.onsen-thanh-thuy.fact.0.value":"Thanh Thuỷ, Phú Thọ, Việt Nam","project.onsen-thanh-thuy.fact.1.label":"Loại hình","project.onsen-thanh-thuy.fact.1.value":"Onsen & Wellness","project.onsen-thanh-thuy.fact.2.label":"Tư liệu","project.onsen-thanh-thuy.fact.2.value":"Concept kiến trúc và cảnh quan","project.ecopark-thanh-hoa.metadata":"ONSEN / Thanh Hoá, Việt Nam","project.ecopark-thanh-hoa.category":"ONSEN","project.ecopark-thanh-hoa.subtitle":"Kiến trúc và cảnh quan Onsen","project.ecopark-thanh-hoa.description":"Phương án Onsen kết hợp những khối nhà mái dốc với sân vườn, mặt nước và các bể tắm giữa cây xanh. Hành lang và khoảng mở dẫn tầm nhìn từ không gian kiến trúc ra cảnh quan.","project.ecopark-thanh-hoa.fact.0.label":"Địa điểm","project.ecopark-thanh-hoa.fact.0.value":"Thanh Hoá, Việt Nam","project.ecopark-thanh-hoa.fact.1.label":"Loại hình","project.ecopark-thanh-hoa.fact.1.value":"Onsen","project.ecopark-thanh-hoa.fact.2.label":"Tư liệu","project.ecopark-thanh-hoa.fact.2.value":"Phối cảnh thiết kế","project.nam-o-residence.metadata":"NHÀ Ở / Đà Nẵng, Việt Nam","project.nam-o-residence.category":"NHÀ Ở","project.nam-o-residence.subtitle":"Nhà ở với khoảng mở và không gian xanh","project.nam-o-residence.description":"Phương án Nam Ô Residence tại Đà Nẵng lấy cảm hứng từ nghệ thuật xếp khối Tsumiki. Các khối nhà được tổ chức để kết hợp không gian ở với cây xanh, tối ưu thông gió, chiếu sáng tự nhiên và kết nối cộng đồng.","project.nam-o-residence.fact.0.label":"Địa điểm","project.nam-o-residence.fact.0.value":"Hoà Hiệp Bắc, Liên Chiểu, Đà Nẵng","project.nam-o-residence.fact.1.label":"Loại hình","project.nam-o-residence.fact.1.value":"Chung cư / nhà ở xã hội","project.nam-o-residence.fact.2.label":"Tư liệu","project.nam-o-residence.fact.2.value":"Phương án concept","project.hakuba-hotel.metadata":"KHÁCH SẠN / Hakuba, Nagano, Nhật Bản","project.hakuba-hotel.category":"KHÁCH SẠN","project.hakuba-hotel.subtitle":"Tinh thần Ryokan trong kiến trúc đương đại","project.hakuba-hotel.description":"Phương án Hakuba Hotel tại Nagano diễn giải tinh thần của Ryokan truyền thống bằng ngôn ngữ kiến trúc hiện đại. Mái dốc, những khoảng hiên và vật liệu gỗ kết nối trải nghiệm lưu trú với cảnh quan núi rừng Nhật Bản.","project.hakuba-hotel.fact.0.label":"Địa điểm","project.hakuba-hotel.fact.0.value":"Hakuba, Nagano, Nhật Bản","project.hakuba-hotel.fact.1.label":"Loại hình","project.hakuba-hotel.fact.1.value":"Khách sạn","project.hakuba-hotel.fact.2.label":"Tư liệu","project.hakuba-hotel.fact.2.value":"Phương án thiết kế","project.thien-mu-hotel.metadata":"KHÁCH SẠN / Huế, Việt Nam","project.thien-mu-hotel.category":"KHÁCH SẠN","project.thien-mu-hotel.subtitle":"Kiến trúc Huế và tinh thần thiền","project.thien-mu-hotel.description":"Phương án khách sạn Thiên Mụ lấy con người làm trung tâm, kết nối kiến trúc Huế với sân vườn và mặt nước. Ý tưởng Chánh Niệm cùng bố cục mở hướng tới trải nghiệm nghỉ ngơi tĩnh tại, hài hòa giữa truyền thống và tiện nghi hiện đại.","project.thien-mu-hotel.fact.0.label":"Địa điểm","project.thien-mu-hotel.fact.0.value":"Huế, Việt Nam","project.thien-mu-hotel.fact.1.label":"Loại hình","project.thien-mu-hotel.fact.1.value":"Khách sạn","project.thien-mu-hotel.fact.2.label":"Tư liệu","project.thien-mu-hotel.fact.2.value":"Phương án concept","project.ecopark-hung-yen.metadata":"ONSEN / Hưng Yên, Việt Nam","project.ecopark-hung-yen.category":"ONSEN","project.ecopark-hung-yen.subtitle":"Trải nghiệm Onsen giữa không gian sống xanh","project.ecopark-hung-yen.description":"Bộ ảnh Onsen tại Ecopark Hưng Yên giới thiệu không gian tắm trong nhà và ngoài trời, mặt nước, đá tự nhiên và kiến trúc mang cảm hứng Nhật Bản giữa cảnh quan xanh của khu đô thị.","project.ecopark-hung-yen.fact.0.label":"Địa điểm","project.ecopark-hung-yen.fact.0.value":"Hưng Yên, Việt Nam","project.ecopark-hung-yen.fact.1.label":"Loại hình","project.ecopark-hung-yen.fact.1.value":"Onsen"},"en":{"project.the-hera-resort.metadata":"RESORT / Quy Nhon, Vietnam","project.the-hera-resort.category":"RESORT","project.the-hera-resort.subtitle":"Santorini-inspired architecture by Tien Bay","project.the-hera-resort.description":"The Hera Resort connects the hills, forest and Tien Bay in Quy Nhon. Inspired by Santorini, the proposal arranges villas, resort apartments and a marina along the terrain, with views towards the sea.","project.the-hera-resort.fact.0.label":"Location","project.the-hera-resort.fact.0.value":"Quy Nhon, Vietnam","project.the-hera-resort.fact.1.label":"Type","project.the-hera-resort.fact.1.value":"Resort","project.the-hera-resort.fact.2.label":"Site area","project.the-hera-resort.fact.2.value":"16.62 ha","project.capital-one.metadata":"MIXED-USE","project.capital-one.category":"MIXED-USE","project.capital-one.subtitle":"A retail and office complex","project.capital-one.description":"The Capital One proposal explores a journey through layers of space, from earth and water to the sky and the universe. The design combines retail, offices and landscape, with a glass façade and lighting that emphasise its vertical form.","project.capital-one.fact.0.label":"Type","project.capital-one.fact.0.value":"Retail and office complex","project.capital-one.fact.1.label":"Documentation","project.capital-one.fact.1.value":"Concept proposal","project.kawara-my-an.metadata":"ONSEN RESORT / Hue, Vietnam","project.kawara-my-an.category":"ONSEN RESORT","project.kawara-my-an.subtitle":"Resort spaces and the Onsen experience","project.kawara-my-an.description":"Kawara My An Onsen Resort in Hue brings together accommodation, gardens and mineral bathing in the Japanese tradition. The photographs show bathing areas, guest rooms and landscapes connected by water.","project.kawara-my-an.fact.0.label":"Location","project.kawara-my-an.fact.0.value":"Hue, Vietnam","project.kawara-my-an.fact.1.label":"Type","project.kawara-my-an.fact.1.value":"Onsen resort","project.aegis-hospital.metadata":"HOSPITAL","project.aegis-hospital.category":"HOSPITAL","project.aegis-hospital.subtitle":"An architectural proposal for a hospital","project.aegis-hospital.description":"The Aegis International Hospital proposal arranges tower volumes with green spaces between them. The presentation includes overall perspectives, façade studies and the open spaces between buildings.","project.aegis-hospital.fact.0.label":"Type","project.aegis-hospital.fact.0.value":"International hospital","project.aegis-hospital.fact.1.label":"Documentation","project.aegis-hospital.fact.1.value":"Design proposal","project.onsen-thanh-thuy.metadata":"ONSEN & WELLNESS / Phu Tho, Vietnam","project.onsen-thanh-thuy.category":"ONSEN & WELLNESS","project.onsen-thanh-thuy.subtitle":"Ryokan architecture and resort landscapes","project.onsen-thanh-thuy.description":"The Onsen Wellness Thanh Thuy concept draws inspiration from Kinosaki and traditional Japanese Ryokan architecture. A waterside landscape axis connects resort spaces, pedestrian streets, gardens and Onsen experiences, creating a wellness village closely connected to nature.","project.onsen-thanh-thuy.fact.0.label":"Location","project.onsen-thanh-thuy.fact.0.value":"Thanh Thuy, Phu Tho, Vietnam","project.onsen-thanh-thuy.fact.1.label":"Type","project.onsen-thanh-thuy.fact.1.value":"Onsen & Wellness","project.onsen-thanh-thuy.fact.2.label":"Documentation","project.onsen-thanh-thuy.fact.2.value":"Architectural and landscape concept","project.ecopark-thanh-hoa.metadata":"ONSEN / Thanh Hoa, Vietnam","project.ecopark-thanh-hoa.category":"ONSEN","project.ecopark-thanh-hoa.subtitle":"Onsen architecture and landscape","project.ecopark-thanh-hoa.description":"The Onsen proposal combines pitched-roof buildings with gardens, water features and bathing pools surrounded by greenery. Corridors and openings draw views from the architecture into the landscape.","project.ecopark-thanh-hoa.fact.0.label":"Location","project.ecopark-thanh-hoa.fact.0.value":"Thanh Hoa, Vietnam","project.ecopark-thanh-hoa.fact.1.label":"Type","project.ecopark-thanh-hoa.fact.1.value":"Onsen","project.ecopark-thanh-hoa.fact.2.label":"Documentation","project.ecopark-thanh-hoa.fact.2.value":"Design visualisations","project.nam-o-residence.metadata":"RESIDENTIAL / Da Nang, Vietnam","project.nam-o-residence.category":"RESIDENTIAL","project.nam-o-residence.subtitle":"Homes with open spaces and greenery","project.nam-o-residence.description":"The Nam O Residence proposal in Da Nang takes inspiration from Tsumiki block-building. Its residential volumes are arranged with greenery to improve ventilation, natural light and connections within the community.","project.nam-o-residence.fact.0.label":"Location","project.nam-o-residence.fact.0.value":"Hoa Hiep Bac, Lien Chieu, Da Nang","project.nam-o-residence.fact.1.label":"Type","project.nam-o-residence.fact.1.value":"Apartments / social housing","project.nam-o-residence.fact.2.label":"Documentation","project.nam-o-residence.fact.2.value":"Concept proposal","project.hakuba-hotel.metadata":"HOTEL / Hakuba, Nagano, Japan","project.hakuba-hotel.category":"HOTEL","project.hakuba-hotel.subtitle":"The spirit of Ryokan in contemporary architecture","project.hakuba-hotel.description":"The Hakuba Hotel proposal in Nagano interprets the spirit of a traditional Ryokan through contemporary architecture. Pitched roofs, verandas and timber connect the guest experience with Japan's mountain and forest landscapes.","project.hakuba-hotel.fact.0.label":"Location","project.hakuba-hotel.fact.0.value":"Hakuba, Nagano, Japan","project.hakuba-hotel.fact.1.label":"Type","project.hakuba-hotel.fact.1.value":"Hotel","project.hakuba-hotel.fact.2.label":"Documentation","project.hakuba-hotel.fact.2.value":"Design proposal","project.thien-mu-hotel.metadata":"HOTEL / Hue, Vietnam","project.thien-mu-hotel.category":"HOTEL","project.thien-mu-hotel.subtitle":"Hue architecture and a spirit of mindfulness","project.thien-mu-hotel.description":"The Thien Mu Hotel proposal puts people at its centre, connecting Hue's architecture with gardens and water. A concept of mindfulness and an open layout create a peaceful stay, balancing tradition with modern comfort.","project.thien-mu-hotel.fact.0.label":"Location","project.thien-mu-hotel.fact.0.value":"Hue, Vietnam","project.thien-mu-hotel.fact.1.label":"Type","project.thien-mu-hotel.fact.1.value":"Hotel","project.thien-mu-hotel.fact.2.label":"Documentation","project.thien-mu-hotel.fact.2.value":"Concept proposal","project.ecopark-hung-yen.metadata":"ONSEN / Hung Yen, Vietnam","project.ecopark-hung-yen.category":"ONSEN","project.ecopark-hung-yen.subtitle":"An Onsen experience within a green living environment","project.ecopark-hung-yen.description":"The photographs of Onsen at Ecopark Hung Yen show indoor and outdoor bathing spaces, water, natural stone and Japanese-inspired architecture set within the development's green landscape.","project.ecopark-hung-yen.fact.0.label":"Location","project.ecopark-hung-yen.fact.0.value":"Hung Yen, Vietnam","project.ecopark-hung-yen.fact.1.label":"Type","project.ecopark-hung-yen.fact.1.value":"Onsen"}};
